def can_reach_boundary(grid, start_pos):
    rows, cols = grid.shape
    visited = set()
    for r in range(rows):
        visited.add((r, 0))
        visited.add((r, cols-1))
    for c in range(cols):
        visited.add((0, c))
        visited.add((rows-1, c))

    queue = [start_pos]
    visited.add(start_pos)

    while queue:
        r, c = queue.pop(0)
        if (r, c) == start_pos:
            continue
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited:
                    if grid[nr, nc] != 5:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

    return False  # Can't reach boundary means it's enclosed

